insert into public.lessons (pillar_id, slug, title, summary, difficulty, learning_objectives, content, estimated_minutes, is_published, sort_order, source_references)
select p.id, 'money-in-money-out', 'Money In, Money Out', 'Where your money comes from, where it goes, and the difference between needs and wants.', 'beginner', array['Identify common sources of money for a student', 'Sort spending into needs and wants', 'Explain why tracking spending helps you decide better']::text[], '[{"type":"paragraph","text":"Before you can plan money, you need to see it clearly. Every plan starts with two simple questions: how much comes in, and where does it go?"},{"type":"heading","text":"Money in"},{"type":"paragraph","text":"For most students, money comes from a monthly allowance, gifts on birthdays or festivals, scholarships, or occasional part-time work like tutoring younger children. Some of this is regular, and some is one-time."},{"type":"callout","tone":"key","title":"Regular vs one-time","text":"Plan your everyday spending around regular money (like a fixed allowance). Treat one-time money (like a Diwali gift) as a chance to save or reach a goal faster."},{"type":"heading","text":"Money out: needs and wants"},{"type":"definition","term":"Need","text":"Something you must pay for to live, study or stay safe, such as travel to college, basic food, or required study materials."},{"type":"definition","term":"Want","text":"Something that is nice to have but not essential, such as a new game, eating out with friends, or upgraded earphones."},{"type":"example","title":"Priya''s month","text":"Priya gets ₹2,500 a month. Here is how she sorted her spending:","rows":[{"label":"Bus pass (need)","amount":"₹600"},{"label":"Canteen lunches (need)","amount":"₹700"},{"label":"Notebooks and pens (need)","amount":"₹250"},{"label":"Movie with friends (want)","amount":"₹350"},{"label":"Mobile game top-up (want)","amount":"₹200"},{"label":"Left over","amount":"₹400"}]},{"type":"paragraph","text":"Wants are not bad. The goal is to cover needs first, then choose wants on purpose instead of by habit."},{"type":"activity","title":"Try it","prompt":"List everything you spent money on last week. Mark each item N (need) or W (want). Which surprised you?"},{"type":"check","question":"Which of these is most likely a need for a student who travels to college?","options":["A new phone cover","A monthly bus pass","A streaming subscription"],"answerIndex":1,"explanation":"Getting to college is essential, so the bus pass is a need. The others are wants."}]'::jsonb, 6, true, 1, '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."},{"title":"National Centre for Financial Education","publisher":"NCFE (promoted by RBI, SEBI, IRDAI and PFRDA)","url":"https://ncfe.org.in/","note":"Financial education material for students and the public."},{"title":"Own Your Future","publisher":"Vanguard","url":"https://ownyourfuture.vanguard.com/","note":"US-focused financial-wellness material; used only for general budgeting and saving principles."}]'::jsonb
from public.learning_pillars p where p.slug = 'plan-and-budget'
