insert into public.lessons (pillar_id, slug, title, summary, difficulty, learning_objectives, content, estimated_minutes, is_published, sort_order, source_references)
select p.id, 'build-your-first-budget', 'Build Your First Budget', 'Turn your money in and money out into a simple monthly plan, including savings.', 'beginner', array['Create a simple monthly budget', 'Include planned savings as part of the budget', 'Check that all allocations add up to what you have']::text[], '[{"type":"paragraph","text":"A budget is a plan for your money before you spend it. It does not have to be complicated. A notebook, a phone note or a spreadsheet works."},{"type":"heading","text":"Four steps to a budget"},{"type":"list","style":"number","items":["Write down the money you expect this month.","List your needs and their costs.","Decide how much to save. Treat saving like a bill you pay yourself.","Use what is left for wants, and stop when it runs out."]},{"type":"callout","tone":"tip","title":"Save first, not last","text":"If you wait to save \"whatever is left\", there is often nothing left. Set aside your savings amount as soon as you receive money."},{"type":"example","title":"Aarav''s budget check","text":"Aarav receives ₹2,000. He plans: travel ₹650, food ₹450, study materials ₹300 and savings ₹400.","rows":[{"label":"Money in","amount":"₹2,000"},{"label":"Travel","amount":"− ₹650"},{"label":"Food","amount":"− ₹450"},{"label":"Study materials","amount":"− ₹300"},{"label":"Savings","amount":"− ₹400"},{"label":"Remaining for wants","amount":"₹200"}]},{"type":"paragraph","text":"Notice that savings is subtracted like any other allocation. Forgetting to include it is one of the most common budgeting mistakes."},{"type":"heading","text":"Track and adjust"},{"type":"paragraph","text":"Write down what you actually spend for a few weeks. Compare it with your plan. If food always costs more than planned, adjust the plan rather than pretending it will change by itself."},{"type":"callout","tone":"key","title":"A starting idea, not a rule","text":"Some people split money into needs, wants and savings using a fixed ratio. Ratios can be a helpful start, but your real costs matter more. Build the plan around your own numbers."},{"type":"check","question":"Meena has ₹1,500. Needs cost ₹900 and she wants to save ₹300. How much is left for wants?","options":["₹600","₹300","₹1,200"],"answerIndex":1,"explanation":"₹1,500 − ₹900 − ₹300 = ₹300."}]'::jsonb, 8, true, 2, '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."},{"title":"National Centre for Financial Education","publisher":"NCFE (promoted by RBI, SEBI, IRDAI and PFRDA)","url":"https://ncfe.org.in/","note":"Financial education material for students and the public."},{"title":"Own Your Future","publisher":"Vanguard","url":"https://ownyourfuture.vanguard.com/","note":"US-focused financial-wellness material; used only for general budgeting and saving principles."}]'::jsonb
