insert into public.lessons (pillar_id, slug, title, summary, difficulty, learning_objectives, content, estimated_minutes, is_published, sort_order, source_references)
select p.id, 'goals-and-trade-offs', 'Goals and Trade-Offs', 'Set clear savings goals and make choices when you cannot afford everything at once.', 'beginner', array['Write a specific savings goal with an amount and a deadline', 'Add up the combined cost of several plans', 'Make a trade-off when plans exceed available money']::text[], '[{"type":"paragraph","text":"A goal turns \"I should save\" into \"I will save ₹1,200 for a calculator by March.\" Specific goals are easier to follow."},{"type":"heading","text":"A good goal has"},{"type":"list","style":"bullet","items":["A clear purpose (what it is for)","An amount in rupees","A deadline","A monthly or weekly saving amount that gets you there"]},{"type":"example","title":"Working backwards","text":"Ravi wants ₹1,800 for a school trip in 6 months. ₹1,800 ÷ 6 = ₹300 per month. If ₹300 is too much, he can start earlier, save a gift, or look for a cheaper option."},{"type":"heading","text":"Trade-offs"},{"type":"paragraph","text":"A trade-off means giving up one thing to have another. It is easy to think \"each item is affordable\" without adding them together."},{"type":"example","title":"Rohan''s plans","text":"Rohan has ₹900 after essential expenses and wants a ₹650 game, a ₹300 outing and to save ₹200.","rows":[{"label":"Game","amount":"₹650"},{"label":"Outing","amount":"₹300"},{"label":"Savings","amount":"₹200"},{"label":"Total plans","amount":"₹1,150"},{"label":"Available","amount":"₹900"},{"label":"Short by","amount":"₹250"}]},{"type":"paragraph","text":"Rohan must change something: wait a month for the game, choose a cheaper outing, or look for the game on sale. Dropping savings entirely should not be the automatic choice."},{"type":"callout","tone":"tip","title":"Rank your priorities","text":"When plans add up to more than you have, rank them. Fund the most important first, then see what fits."},{"type":"check","question":"You have ₹500. Plans: ₹250 + ₹200 + ₹150. What is true?","options":["Everything fits","Plans total ₹600, so you must adjust ₹100","Plans total ₹450"],"answerIndex":1,"explanation":"₹250 + ₹200 + ₹150 = ₹600, which is ₹100 more than ₹500."}]'::jsonb, 7, true, 3, '[{"title":"National Centre for Financial Education","publisher":"NCFE (promoted by RBI, SEBI, IRDAI and PFRDA)","url":"https://ncfe.org.in/","note":"Financial education material for students and the public."},{"title":"Own Your Future","publisher":"Vanguard","url":"https://ownyourfuture.vanguard.com/","note":"US-focused financial-wellness material; used only for general budgeting and saving principles."}]'::jsonb
