insert into public.lessons (pillar_id, slug, title, summary, difficulty, learning_objectives, content, estimated_minutes, is_published, sort_order, source_references)
select p.id, 'why-save-emergency-fund', 'Why Save? Your Emergency Cushion', 'Saving gives you choices. Learn how emergency savings work and how to rebuild them.', 'beginner', array['Give three reasons people save', 'Explain what an emergency fund is for', 'Plan how to rebuild savings after using them']::text[], '[{"type":"paragraph","text":"Saving means keeping some money aside instead of spending it now. People save for goals (a cycle, a course), for opportunities, and for surprises."},{"type":"heading","text":"The emergency cushion"},{"type":"paragraph","text":"An emergency fund is money kept aside, easy to reach, for necessary expenses you did not expect, such as a broken calculator before an exam or a sudden medical cost."},{"type":"callout","tone":"key","title":"Emergency means necessary and unexpected","text":"A sale on sneakers is not an emergency. A broken item you need for study is."},{"type":"example","title":"Nisha''s calculator","text":"Nisha has ₹1,200 saved. Her calculator stops working before an exam, and a suitable replacement costs ₹700. She uses ₹700 from savings, buys the calculator, and plans to rebuild by saving ₹150 a month.","rows":[{"label":"Savings before","amount":"₹1,200"},{"label":"Calculator","amount":"− ₹700"},{"label":"Savings after","amount":"₹500"},{"label":"Rebuild plan","amount":"+ ₹150 / month"}]},{"type":"paragraph","text":"Using savings for a real emergency is exactly what they are for. The important part is the plan to rebuild them afterwards."},{"type":"heading","text":"Where to keep emergency money"},{"type":"paragraph","text":"Emergency money should be safe and quick to access, such as a savings bank account. It should not be put into something whose value can fall, or that takes time to withdraw."},{"type":"check","question":"Which is the best use of an emergency fund?","options":["A limited-time phone offer","Replacing a broken pair of spectacles you need for class","A trip with friends"],"answerIndex":1,"explanation":"Spectacles you need to study are necessary and unexpected when they break."}]'::jsonb, 6, true, 1, '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."},{"title":"National Centre for Financial Education","publisher":"NCFE (promoted by RBI, SEBI, IRDAI and PFRDA)","url":"https://ncfe.org.in/","note":"Financial education material for students and the public."},{"title":"Own Your Future","publisher":"Vanguard","url":"https://ownyourfuture.vanguard.com/","note":"US-focused financial-wellness material; used only for general budgeting and saving principles."}]'::jsonb
