insert into public.lessons (pillar_id, slug, title, summary, difficulty, learning_objectives, content, estimated_minutes, is_published, sort_order, source_references)
select p.id, 'bank-accounts-and-cards', 'Bank Accounts, Cards and Nominees', 'Savings accounts, deposits, debit vs credit cards, KYC and what a nominee really means.', 'beginner', array['Describe a savings account, fixed deposit and recurring deposit', 'Explain the difference between a debit card and a credit card', 'Explain what a bank nominee is and is not']::text[], '[{"type":"heading","text":"Savings account"},{"type":"paragraph","text":"A savings account keeps your money safe with a bank and usually pays a small amount of interest. Banks need you to complete KYC (Know Your Customer) by showing identity and address documents. Many banks let students aged 10 and above operate their own account, often with limits; younger students can hold one with a parent or guardian."},{"type":"definition","term":"Fixed Deposit (FD)","text":"You deposit a lump sum for a fixed period at an agreed interest rate. Withdrawing early may reduce the interest you receive."},{"type":"definition","term":"Recurring Deposit (RD)","text":"You deposit a fixed amount every month for a chosen period. Useful for building a habit of saving."},{"type":"callout","tone":"key","title":"Deposit insurance","text":"In India, bank deposits are insured by DICGC up to a limit per depositor per bank. Check dicgc.org.in for the current limit and rules."},{"type":"heading","text":"Debit card vs credit card"},{"type":"list","style":"bullet","items":["Debit card: spends money already in your linked bank account. Paying ₹180 reduces your balance by ₹180 once the transaction is processed.","Credit card: the bank lends you money to pay. You must repay by the due date, or you may pay high interest and fees. Credit cards are usually only available to adults."]},{"type":"callout","tone":"warning","title":"A card payment is not free money","text":"Neither card creates money. A debit card uses your money now; a credit card is a loan you must repay."},{"type":"heading","text":"What is a nominee?"},{"type":"paragraph","text":"A nominee is a person you name who can receive or claim the money in your account after your death, following the applicable rules. Nominating someone makes the process easier for your family."},{"type":"list","style":"bullet","items":["A nominee does not get to use your account while you are alive.","A nominee does not receive monthly profits or interest.","Nomination does not guarantee any interest or return.","Banks have their own forms and rules for nominees; ask your bank for details."]},{"type":"check","question":"Tara pays ₹180 with her debit card. What usually happens?","options":["Her balance increases by ₹180","The ₹180 is deducted from her linked bank account","The payment becomes a loan"],"answerIndex":1,"explanation":"A debit card pays from money in the linked account."}]'::jsonb, 9, true, 2, '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."},{"title":"Deposit insurance information","publisher":"Deposit Insurance and Credit Guarantee Corporation","url":"https://www.dicgc.org.in/","note":"Explains deposit insurance cover for bank deposits; check current limits on the site."},{"title":"Banking Terminologies (document hosted on Scribd)","publisher":"Scribd user upload","url":"https://www.scribd.com/document/294551371/Banking-Terminologies","note":"Older glossary of general banking terms (cheques, interest, overdraft). Some figures in it are outdated; not used for current rules."}]'::jsonb
