insert into public.lessons (pillar_id, slug, title, summary, difficulty, learning_objectives, content, estimated_minutes, is_published, sort_order, source_references)
select p.id, 'reading-a-bank-statement', 'Reading a Bank Statement', 'Decode common transaction labels and spot entries you do not recognise.', 'beginner', array['Read the columns of a bank statement', 'Recognise common transaction labels such as UPI, NEFT, ATM WDL and INT CR', 'Know what to do when an entry looks unfamiliar']::text[], '[{"type":"paragraph","text":"A bank statement lists every transaction in your account: the date, a description, money going out (debit), money coming in (credit) and the balance after each entry."},{"type":"heading","text":"Common labels"},{"type":"definition","term":"UPI/…","text":"A payment sent or received through UPI, often followed by the name or ID of the other person or shop."},{"type":"definition","term":"NEFT / IMPS / RTGS","text":"Different systems used to transfer money between bank accounts."},{"type":"definition","term":"ATM WDL","text":"Cash withdrawn at an ATM."},{"type":"definition","term":"POS","text":"A card payment made at a shop''s card machine (Point of Sale)."},{"type":"definition","term":"INT CR / INT.PD","text":"Interest credited to your account by the bank."},{"type":"definition","term":"CHQ / CLG","text":"A cheque transaction or cheque clearing."},{"type":"callout","tone":"tip","title":"Labels vary","text":"Each bank writes descriptions a little differently. If you are unsure what a label means, ask your bank through its official app, website or branch."},{"type":"heading","text":"If something looks wrong"},{"type":"paragraph","text":"If you see a transaction you did not make, such as an ATM withdrawal you do not remember, contact your bank promptly through its official app, website or the phone number printed on your card or passbook. Do not share your statement publicly and never give an OTP or PIN to anyone who contacts you claiming to help."},{"type":"check","question":"What does \"ATM WDL ₹1,000\" most likely mean?","options":["₹1,000 deposited by cheque","₹1,000 withdrawn in cash at an ATM","₹1,000 interest credited"],"answerIndex":1,"explanation":"ATM WDL is short for ATM withdrawal."}]'::jsonb, 7, true, 3, '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."},{"title":"Banking Terminologies (document hosted on Scribd)","publisher":"Scribd user upload","url":"https://www.scribd.com/document/294551371/Banking-Terminologies","note":"Older glossary of general banking terms (cheques, interest, overdraft). Some figures in it are outdated; not used for current rules."}]'::jsonb
