on conflict (slug) do nothing;
insert into public.lessons (pillar_id, slug, title, summary, difficulty, learning_objectives, content, estimated_minutes, is_published, sort_order, source_references)
select p.id, 'interest-and-compound-growth', 'Interest and Compound Growth', 'How interest works and why leaving earnings invested can help money grow faster.', 'intermediate', array['Calculate simple interest on a small amount', 'Explain compounding as earning on earlier earnings', 'Recognise that compounding does not remove risk']::text[], '[{"type":"paragraph","text":"Interest is what a bank pays you for keeping money with it, or what you pay a lender for borrowing. When you save, interest works for you; when you borrow, it works against you."},{"type":"heading","text":"Simple interest"},{"type":"example","title":"One year at 4%","text":"Hypothetical example: ₹1,000 at 4% simple interest for one year earns ₹40. You end with ₹1,040."},{"type":"heading","text":"Compound growth"},{"type":"paragraph","text":"Compounding happens when earnings are added to your balance, so the next round of earnings is calculated on a bigger amount."},{"type":"example","title":"Leaving earnings in (hypothetical, 8% per year, no fees)","text":"These numbers only illustrate the idea. Real returns vary and can be negative.","rows":[{"label":"Start","amount":"₹1,000"},{"label":"After year 1","amount":"₹1,080"},{"label":"After year 2","amount":"₹1,166"},{"label":"After year 3","amount":"₹1,260"},{"label":"If ₹80 was withdrawn each year","amount":"₹1,000 + ₹240 taken out"}]},{"type":"paragraph","text":"In year 2 the growth is ₹86, not ₹80, because the earlier ₹80 also earned something. Over many years, this difference becomes large."},{"type":"callout","tone":"warning","title":"Compounding is not a guarantee","text":"Compounding helps only when returns are positive. Investments can lose value, and compounding does not prevent that."},{"type":"callout","tone":"tip","title":"Time is your advantage","text":"Starting to save early gives compounding more years to work, even with small amounts."},{"type":"check","question":"Why does a balance grow faster when earnings are left invested?","options":["Banks pay a bonus for not withdrawing","Future earnings are calculated on the original amount plus past earnings","The investment can no longer lose money"],"answerIndex":1,"explanation":"That is the idea of compounding. It does not remove risk."}]'::jsonb, 8, true, 4, '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."},{"title":"SEBI Investor education portal","publisher":"Securities and Exchange Board of India","url":"https://investor.sebi.gov.in/","note":"Investor education on money matters, investment avenues and risk."},{"title":"Own Your Future","publisher":"Vanguard","url":"https://ownyourfuture.vanguard.com/","note":"US-focused financial-wellness material; used only for general budgeting and saving principles."}]'::jsonb
from public.learning_pillars p where p.slug = 'save-and-manage'
on conflict (slug) do nothing;
insert into public.lessons (pillar_id, slug, title, summary, difficulty, learning_objectives, content, estimated_minutes, is_published, sort_order, source_references)
select p.id, 'saving-vs-investing', 'Saving vs Investing', 'Risk, return and time horizon: match where you keep money to when you need it.', 'intermediate', array['Explain the difference between saving and investing', 'Describe the link between risk and potential return', 'Choose a suitable place for money based on when it is needed']::text[], '[{"type":"paragraph","text":"Saving keeps money safe and available. Investing puts money into things like shares or mutual funds that may grow more over time, but whose value can also fall."},{"type":"heading","text":"Risk and return"},{"type":"paragraph","text":"Investments that might grow more usually come with more ups and downs. There is no reliable way to get high returns with no risk. Anyone promising that is a warning sign."},{"type":"heading","text":"Time horizon"},{"type":"definition","term":"Time horizon","text":"How long until you need the money."},{"type":"list","style":"bullet","items":["Needed within months (exam fee, school trip): keep it safe and accessible, such as in a savings account or a suitable deposit, after checking any fees or conditions.","Needed in many years (higher studies far away): some people consider investing a part, because there is time to recover from falls. This depends on the person and should be discussed with parents or a qualified, registered adviser."]},{"type":"example","title":"Meera''s trip","text":"Meera needs ₹3,000 in three months and has ₹2,400. The gap is ₹600, so saving ₹200 a month in a safe, accessible place covers it. Putting her ₹2,400 into a volatile investment could leave her short if prices fall."},{"type":"example","title":"Ananya''s exam fee","text":"Ananya needs exactly ₹4,000 in two months. An asset that rose this week might fall next week. A short-term drop or a delay in withdrawing could mean she cannot pay the fee."},{"type":"callout","tone":"warning","title":"Money needed soon","text":"Money for a fixed, near-term, essential expense should not be exposed to price swings."},{"type":"check","question":"You need ₹2,000 for a course fee next month. Where should it be?","options":["In shares that rose last week","Somewhere safe and easy to withdraw","In a scheme promising to double it"],"answerIndex":1,"explanation":"Short-term essential money should stay safe and accessible."}]'::jsonb, 8, true, 1, '[{"title":"SEBI Investor education portal","publisher":"Securities and Exchange Board of India","url":"https://investor.sebi.gov.in/","note":"Investor education on money matters, investment avenues and risk."},{"title":"National Centre for Financial Education","publisher":"NCFE (promoted by RBI, SEBI, IRDAI and PFRDA)","url":"https://ncfe.org.in/","note":"Financial education material for students and the public."},{"title":"Own Your Future","publisher":"Vanguard","url":"https://ownyourfuture.vanguard.com/","note":"US-focused financial-wellness material; used only for general budgeting and saving principles."}]'::jsonb
from public.learning_pillars p where p.slug = 'understand-investing'
on conflict (slug) do nothing;
insert into public.lessons (pillar_id, slug, title, summary, difficulty, learning_objectives, content, estimated_minutes, is_published, sort_order, source_references)
select p.id, 'inflation-and-purchasing-power', 'Inflation and Purchasing Power', 'Why prices rise over time and how that affects what your savings can buy.', 'intermediate', array['Define inflation and purchasing power', 'Compare the growth of savings with the growth of prices']::text[], '[{"type":"definition","term":"Inflation","text":"The general rise in prices over time."},{"type":"definition","term":"Purchasing power","text":"How much you can actually buy with a given amount of money."},{"type":"paragraph","text":"If prices rise faster than your money grows, you can buy less than before, even though you have more rupees."},{"type":"example","title":"The notebook test (hypothetical)","text":"A notebook costs ₹100 today and ₹105 next year. Your ₹100 savings grow to ₹103.","rows":[{"label":"Notebook price next year","amount":"₹105"},{"label":"Your savings next year","amount":"₹103"},{"label":"Short by","amount":"₹2"}]},{"type":"paragraph","text":"Your savings grew, but the notebook grew more expensive faster. Your purchasing power fell."},{"type":"callout","tone":"key","title":"Compare growth with prices","text":"When judging any saving or investment option, ask: is it likely to keep up with rising prices over the time I hold it? For short-term money, safety still comes first."},{"type":"check","question":"Prices rise 6% and your savings grow 4%. What happens to purchasing power?","options":["It increases","It stays the same","It decreases"],"answerIndex":2,"explanation":"Prices grew faster than your money, so you can buy less."}]'::jsonb, 6, true, 2, '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."},{"title":"SEBI Investor education portal","publisher":"Securities and Exchange Board of India","url":"https://investor.sebi.gov.in/","note":"Investor education on money matters, investment avenues and risk."}]'::jsonb
from public.learning_pillars p where p.slug = 'understand-investing'
on conflict (slug) do nothing;
insert into public.lessons (pillar_id, slug, title, summary, difficulty, learning_objectives, content, estimated_minutes, is_published, sort_order, source_references)
select p.id, 'diversification-fees-and-compounding', 'Diversification, Fees and Past Performance', 'Why spreading money out helps, how small fees add up, and why past returns are not promises.', 'intermediate', array['Explain diversification and concentration risk', 'Compare the effect of different fees', 'Explain why past performance does not guarantee future results']::text[], '[{"type":"heading","text":"Diversification"},{"type":"paragraph","text":"Putting all your money into one company''s shares means one bad event at that company can hurt you a lot. This is concentration risk. Spreading money across many companies or types of investments is called diversification."},{"type":"callout","tone":"warning","title":"Diversification reduces, not removes, risk","text":"A diversified portfolio can still fall in value, for example when the whole market drops. It does not guarantee a profit."},{"type":"heading","text":"Fees matter"},{"type":"paragraph","text":"Investment products charge fees. Mutual funds in India show this as an expense ratio. Fees are taken whether the investment does well or not."},{"type":"example","title":"Two similar funds (hypothetical)","text":"Both funds earn the same return before fees on the same amount.","rows":[{"label":"Fund A fee per year","amount":"₹20"},{"label":"Fund B fee per year","amount":"₹100"},{"label":"Extra kept with Fund A each year","amount":"₹80"}]},{"type":"paragraph","text":"All else being equal, the lower fee leaves more money invested, and that extra money can also compound. A higher fee does not automatically mean better results."},{"type":"heading","text":"Past performance"},{"type":"paragraph","text":"An investment that went up last year may go down this year. Past returns tell you what happened, not what will happen."},{"type":"callout","tone":"tip","title":"Check registration","text":"In India, investment advisers and many market intermediaries must be registered with SEBI. You can check registration on SEBI''s website."},{"type":"check","question":"What is one benefit of diversification?","options":["It guarantees profit every year","A problem at one company has a smaller effect on the whole portfolio","It removes all risk"],"answerIndex":1,"explanation":"Diversification reduces concentration risk but cannot remove all risk."}]'::jsonb, 8, true, 3, '[{"title":"SEBI Investor education portal","publisher":"Securities and Exchange Board of India","url":"https://investor.sebi.gov.in/","note":"Investor education on money matters, investment avenues and risk."},{"title":"National Centre for Financial Education","publisher":"NCFE (promoted by RBI, SEBI, IRDAI and PFRDA)","url":"https://ncfe.org.in/","note":"Financial education material for students and the public."}]'::jsonb
from public.learning_pillars p where p.slug = 'understand-investing'
on conflict (slug) do nothing;
insert into public.lessons (pillar_id, slug, title, summary, difficulty, learning_objectives, content, estimated_minutes, is_published, sort_order, source_references)
select p.id, 'upi-safety-basics', 'UPI Safety Basics', 'Your UPI PIN sends money; it never receives it. Learn the common UPI tricks.', 'beginner', array['Explain when a UPI PIN is needed', 'Recognise fake refund and QR-code scams', 'Verify payment requests safely']::text[], '[{"type":"callout","tone":"key","title":"The golden rule","text":"You enter your UPI PIN only to send money or approve a payment from your account. You never need your PIN to receive money."},{"type":"heading","text":"Common tricks"},{"type":"list","style":"bullet","items":["Fake refund: \"Scan this QR code and enter your PIN to get your ₹750 refund.\" Scanning and entering a PIN sends money out.","Payment requests that look like incoming money: a request appears in your app; approving it with your PIN pays the other person.","Wrong transfer story: a stranger says they sent money by mistake and asks you to send it back. Check your actual bank balance in your official app first.","Screen-sharing apps: someone asks you to install an app so they can \"help\". This can let them see your screen and codes."]},{"type":"heading","text":"Stay safe"},{"type":"list","style":"number","items":["Never share your UPI PIN or OTP with anyone, including people claiming to be from a bank.","Read every payment screen: check the amount and whether money is going out.","Verify refunds through the official app or website of the seller, not through a link or QR code sent by a stranger.","If you approved something by mistake, contact your bank immediately through official channels."]},{"type":"callout","tone":"warning","title":"This platform will never ask","text":"This learning platform never asks for your bank details, PIN or OTP. Do not enter real financial information anywhere it is not needed."},{"type":"check","question":"A seller says you must enter your UPI PIN to receive a refund. What is true?","options":["That is normal","A PIN is not needed to receive money; this is a warning sign","Only if the amount is small"],"answerIndex":1,"explanation":"Entering a PIN authorises money leaving your account."}]'::jsonb, 7, true, 1, '[{"title":"UPI product information and safety guidance","publisher":"National Payments Corporation of India","url":"https://www.npci.org.in/","note":"Operator of UPI. Refer to the official site for current safety advice."},{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."},{"title":"National Cyber Crime Reporting Portal (helpline 1930)","publisher":"Ministry of Home Affairs, Government of India","url":"https://cybercrime.gov.in/","note":"Official channel to report cyber financial fraud."}]'::jsonb
from public.learning_pillars p where p.slug = 'stay-financially-safe'
on conflict (slug) do nothing;
insert into public.lessons (pillar_id, slug, title, summary, difficulty, learning_objectives, content, estimated_minutes, is_published, sort_order, source_references)
select p.id, 'phishing-and-impersonation', 'Phishing and Impersonation', 'Urgent messages, fake links and people pretending to be your bank.', 'beginner', array['Identify the warning signs of a phishing message', 'Explain why a logo or name does not prove a message is real', 'Verify messages through official channels']::text[], '[{"type":"paragraph","text":"Phishing is when someone pretends to be a trusted organisation to trick you into sharing passwords, OTPs, card numbers or other details."},{"type":"heading","text":"Warning signs"},{"type":"list","style":"bullet","items":["Urgency or threats: \"Your account will be blocked in 10 minutes.\"","A link asking you to log in or \"update KYC\".","Requests for OTP, PIN, CVV or password.","Small spelling mistakes or odd website addresses.","Offers that seem too good to be true, like prizes you never entered for."]},{"type":"callout","tone":"warning","title":"Logos can be copied","text":"Anyone can copy a bank''s logo or name. It does not prove a message is genuine."},{"type":"heading","text":"What to do instead"},{"type":"list","style":"number","items":["Do not click the link or call the number in the message.","Open your bank''s official app, or type its official website address yourself.","Call the number printed on your card or passbook if you are unsure.","Report suspicious messages to your bank, and cyber fraud at cybercrime.gov.in or helpline 1930."]},{"type":"check","question":"Which is the strongest sign a message is phishing?","options":["It mentions your bank by name","It creates urgency and asks for login details through a link","It arrives on a weekday"],"answerIndex":1,"explanation":"Urgency plus a request for sensitive details through a link is a classic phishing pattern."}]'::jsonb, 6, true, 2, '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."},{"title":"National Cyber Crime Reporting Portal (helpline 1930)","publisher":"Ministry of Home Affairs, Government of India","url":"https://cybercrime.gov.in/","note":"Official channel to report cyber financial fraud."}]'::jsonb
from public.learning_pillars p where p.slug = 'stay-financially-safe'
on conflict (slug) do nothing;
insert into public.lessons (pillar_id, slug, title, summary, difficulty, learning_objectives, content, estimated_minutes, is_published, sort_order, source_references)
select p.id, 'fake-investment-promises', 'Fake Investment Promises', 'Guaranteed returns, zero risk and "send a small amount first" are major red flags.', 'intermediate', array['Recognise unrealistic investment promises', 'Explain why testing with a small amount proves nothing', 'Know where to check whether an entity is registered']::text[], '[{"type":"paragraph","text":"Social media is full of people promising to multiply your money quickly. Real investments carry risk. Promises of big, fast, guaranteed returns are a warning sign."},{"type":"heading","text":"Red flags"},{"type":"list","style":"bullet","items":["\"Turn ₹2,000 into ₹10,000 in 30 days.\"","\"Zero risk\" or \"guaranteed returns\".","Pressure to act now or keep it secret.","Rewards for bringing in friends (this can be a sign of a pyramid or Ponzi-type scheme).","Screenshots of profits and positive comments, which are easy to fake."]},{"type":"callout","tone":"warning","title":"The \"test amount\" trap","text":"Some scams pay out a small first amount to build trust, then take a much larger payment. A small successful test does not prove anything."},{"type":"heading","text":"Check before you trust"},{"type":"list","style":"bullet","items":["Check whether an adviser or intermediary is registered with SEBI on SEBI''s website.","Report schemes collecting deposits without authorisation on RBI''s Sachet portal.","Talk to a parent, teacher or trusted adult before sending money to anyone online."]},{"type":"check","question":"An influencer promises 5× returns in a month with zero risk. What should you do?","options":["Send a small amount to test","Treat it as a major warning sign and do not send money","Trust the positive comments"],"answerIndex":1,"explanation":"Extraordinary returns with no risk are a serious red flag."}]'::jsonb, 7, true, 3, '[{"title":"SEBI Investor education portal","publisher":"Securities and Exchange Board of India","url":"https://investor.sebi.gov.in/","note":"Investor education on money matters, investment avenues and risk."},{"title":"Sachet portal for reporting illegal deposit schemes","publisher":"Reserve Bank of India","url":"https://sachet.rbi.org.in/","note":"Check and report unauthorised entities collecting deposits."},{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."}]'::jsonb
from public.learning_pillars p where p.slug = 'stay-financially-safe'
on conflict (slug) do nothing;
insert into public.lessons (pillar_id, slug, title, summary, difficulty, learning_objectives, content, estimated_minutes, is_published, sort_order, source_references)
select p.id, 'reporting-fraud-safely', 'Reporting Problems Safely', 'What to do when you spot a transaction you do not recognise.', 'beginner', array['List the first steps after noticing an unrecognised transaction', 'Use verified channels to contact a bank', 'Know the escalation routes available in India']::text[], '[{"type":"paragraph","text":"Noticing a problem quickly and reporting it through the right channel matters. Under RBI''s customer-protection rules, how soon an unauthorised electronic transaction is reported can affect how much of the loss the customer has to bear."},{"type":"heading","text":"First steps"},{"type":"list","style":"number","items":["Contact your bank promptly through its official app, website, or the phone number on your card or passbook.","Ask the bank to block your card or UPI if needed.","Note the date, amount and description of the transaction and keep your complaint reference number.","For cyber fraud, also report at cybercrime.gov.in or call 1930."]},{"type":"callout","tone":"warning","title":"Beware \"recovery\" offers","text":"Scammers sometimes contact victims offering to recover money for a fee or an OTP. Never share credentials with someone who contacts you first."},{"type":"heading","text":"If the bank does not resolve it"},{"type":"paragraph","text":"If your bank does not reply or you are not satisfied after the period the bank tells you, you can escalate through the RBI Integrated Ombudsman Scheme at cms.rbi.org.in."},{"type":"callout","tone":"tip","title":"Keep statements private","text":"Do not post your bank statement or account details on social media, even when asking for help."},{"type":"check","question":"You see \"ATM WDL ₹1,000\" that you did not make. What first?","options":["Ignore it","Contact your bank through a verified channel and report it","Reply to a message offering recovery help"],"answerIndex":1,"explanation":"Report promptly through official bank channels."}]'::jsonb, 6, true, 4, '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."},{"title":"National Cyber Crime Reporting Portal (helpline 1930)","publisher":"Ministry of Home Affairs, Government of India","url":"https://cybercrime.gov.in/","note":"Official channel to report cyber financial fraud."},{"title":"RBI Complaint Management System (Integrated Ombudsman Scheme)","publisher":"Reserve Bank of India","url":"https://cms.rbi.org.in/","note":"Escalation route if a bank does not resolve a complaint."}]'::jsonb
from public.learning_pillars p where p.slug = 'stay-financially-safe'
on conflict (slug) do nothing;

