-- Question 1: The Budget Puzzle
insert into public.quiz_questions (quiz_id, kind, parent_question_id, slug, title, prompt, topic, difficulty, concept, misconception, lesson_id, sort_order, is_published, source_references)
select z.id, 'core', null, 'q01-budget-puzzle', 'The Budget Puzzle', 'Aarav receives ₹2,000. He spends ₹650 on travel, ₹450 on food, and ₹300 on study materials. He also wants to save ₹400. How much money remains after all these allocations?', 'Budgeting', 'beginner', 'Adding up spending and planned savings', 'Forgetting to subtract planned savings (or one of the expenses) when working out what is left.', (select id from public.lessons where slug = 'build-your-first-budget'), 1, true, '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."},{"title":"National Centre for Financial Education","publisher":"NCFE (promoted by RBI, SEBI, IRDAI and PFRDA)","url":"https://ncfe.org.in/","note":"Financial education material for students and the public."}]'::jsonb
from public.quizzes z where z.slug = 'money-rookie'
on conflict (slug) do nothing;
insert into public.quiz_options (question_id, option_key, option_text, sort_order)
select q.id, v.option_key, v.option_text, v.sort_order
from public.quiz_questions q
cross join (values
  ('A', '₹100', 1),
  ('B', '₹200', 2),
  ('C', '₹600', 3),
  ('D', '₹1,000', 4)
) as v(option_key, option_text, sort_order)
where q.slug = 'q01-budget-puzzle'
on conflict (question_id, option_key) do nothing;
insert into public.quiz_answer_keys (question_id, correct_option_id, explanation, teaching_point)
select q.id, o.id, '₹2,000 − ₹650 − ₹450 − ₹300 − ₹400 = ₹200.', 'Account for all spending and planned savings before deciding how much is left.'
from public.quiz_questions q join public.quiz_options o on o.question_id = q.id and o.option_key = 'B'
where q.slug = 'q01-budget-puzzle'
on conflict (question_id) do nothing;
insert into public.quiz_questions (quiz_id, kind, parent_question_id, slug, title, prompt, topic, difficulty, concept, misconception, lesson_id, sort_order, is_published, source_references)
