-- Question 2: Emergency or Temptation?
insert into public.quiz_questions (quiz_id, kind, parent_question_id, slug, title, prompt, topic, difficulty, concept, misconception, lesson_id, sort_order, is_published, source_references)
select z.id, 'core', null, 'q02-emergency-or-temptation', 'Emergency or Temptation?', 'Nisha has ₹1,200 in accessible savings. Her calculator unexpectedly stops working before an exam, and a suitable replacement costs ₹700. What is the most sensible choice?', 'Emergency savings', 'beginner', 'Using and rebuilding emergency savings', 'Believing savings should never be touched, or reaching for a loan before using money set aside for emergencies.', (select id from public.lessons where slug = 'why-save-emergency-fund'), 2, true, '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."},{"title":"National Centre for Financial Education","publisher":"NCFE (promoted by RBI, SEBI, IRDAI and PFRDA)","url":"https://ncfe.org.in/","note":"Financial education material for students and the public."}]'::jsonb
