insert into public.quiz_answer_keys (question_id, correct_option_id, explanation, teaching_point)
select q.id, o.id, 'Emergency savings can help cover necessary, unexpected expenses. Nisha can replace the essential calculator and rebuild her savings afterward.', 'Savings provide flexibility when unexpected needs arise.'
from public.quiz_questions q join public.quiz_options o on o.question_id = q.id and o.option_key = 'B'
where q.slug = 'q02-emergency-or-temptation'
on conflict (question_id) do nothing;
insert into public.quiz_questions (quiz_id, kind, parent_question_id, slug, title, prompt, topic, difficulty, concept, misconception, lesson_id, sort_order, is_published, source_references)
select z.id, 'practice', (select id from public.quiz_questions where slug = 'q02-emergency-or-temptation'), 'p02-emergency-or-temptation', 'Practice: Arjun''s Savings', 'Arjun has ₹2,000 in emergency savings. Which of these is the best reason to use some of it?', 'Emergency savings', 'beginner', 'Using and rebuilding emergency savings', 'Believing savings should never be touched, or reaching for a loan before using money set aside for emergencies.', (select id from public.lessons where slug = 'why-save-emergency-fund'), 2, true, '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."},{"title":"National Centre for Financial Education","publisher":"NCFE (promoted by RBI, SEBI, IRDAI and PFRDA)","url":"https://ncfe.org.in/","note":"Financial education material for students and the public."}]'::jsonb
from public.quizzes z where z.slug = 'money-rookie'
