-- Question 3: Understanding a Bank Nominee
insert into public.quiz_questions (quiz_id, kind, parent_question_id, slug, title, prompt, topic, difficulty, concept, misconception, lesson_id, sort_order, is_published, source_references)
select z.id, 'core', null, 'q03-bank-nominee', 'Understanding a Bank Nominee', 'Kabir''s parent asks him to help understand what a bank nominee is. Which explanation is most accurate?', 'Banking basics', 'beginner', 'Understanding a bank nominee', 'Thinking a nominee can use the account or receives its earnings while the account holder is alive.', (select id from public.lessons where slug = 'bank-accounts-and-cards'), 3, true, '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."},{"title":"Banking Terminologies (document hosted on Scribd)","publisher":"Scribd user upload","url":"https://www.scribd.com/document/294551371/Banking-Terminologies","note":"Older glossary of general banking terms (cheques, interest, overdraft). Some figures in it are outdated; not used for current rules."}]'::jsonb
from public.quizzes z where z.slug = 'money-rookie'
on conflict (slug) do nothing;
insert into public.quiz_options (question_id, option_key, option_text, sort_order)
select q.id, v.option_key, v.option_text, v.sort_order
from public.quiz_questions q
cross join (values
  ('A', 'A nominee receives all account profits every month.', 1),
  ('B', 'A nominee is a designated person who may receive or claim the account proceeds following the account holder''s death, subject to applicable rules.', 2),
  ('C', 'A nominee can freely use the account whenever they want while the account holder is alive.', 3),
  ('D', 'A nominee guarantees that the account will earn interest.', 4)
) as v(option_key, option_text, sort_order)
where q.slug = 'q03-bank-nominee'
on conflict (question_id, option_key) do nothing;
insert into public.quiz_answer_keys (question_id, correct_option_id, explanation, teaching_point)
select q.id, o.id, 'A nominee is designated to facilitate the handling or claim of account proceeds under applicable rules. Nomination does not mean the person automatically has unrestricted access to the account during the account holder''s lifetime.', 'Understand the purpose and limitations of banking arrangements.'
from public.quiz_questions q join public.quiz_options o on o.question_id = q.id and o.option_key = 'B'
where q.slug = 'q03-bank-nominee'
on conflict (question_id) do nothing;
insert into public.quiz_questions (quiz_id, kind, parent_question_id, slug, title, prompt, topic, difficulty, concept, misconception, lesson_id, sort_order, is_published, source_references)
select z.id, 'practice', (select id from public.quiz_questions where slug = 'q03-bank-nominee'), 'p03-bank-nominee', 'Practice: Adding a Nominee', 'Which statement about adding a nominee to a savings account is true?', 'Banking basics', 'beginner', 'Understanding a bank nominee', 'Thinking a nominee can use the account or receives its earnings while the account holder is alive.', (select id from public.lessons where slug = 'bank-accounts-and-cards'), 3, true, '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."},{"title":"Banking Terminologies (document hosted on Scribd)","publisher":"Scribd user upload","url":"https://www.scribd.com/document/294551371/Banking-Terminologies","note":"Older glossary of general banking terms (cheques, interest, overdraft). Some figures in it are outdated; not used for current rules."}]'::jsonb
from public.quizzes z where z.slug = 'money-rookie'
on conflict (slug) do nothing;
insert into public.quiz_options (question_id, option_key, option_text, sort_order)
select q.id, v.option_key, v.option_text, v.sort_order
from public.quiz_questions q
cross join (values
  ('A', 'It helps the account holder''s family claim the money after the account holder''s death, following the bank''s rules.', 1),
  ('B', 'The nominee can withdraw money at any time.', 2),
  ('C', 'The nominee receives the interest every month.', 3),
