insert into public.quiz_answer_keys (question_id, correct_option_id, explanation, teaching_point)
select q.id, o.id, 'Nomination makes it easier to settle the account after the holder''s death. It does not give the nominee access during the holder''s lifetime.', 'A nominee is for later claims, not for current use.'
from public.quiz_questions q join public.quiz_options o on o.question_id = q.id and o.option_key = 'A'
