-- Question 7: Compounding
insert into public.quiz_questions (quiz_id, kind, parent_question_id, slug, title, prompt, topic, difficulty, concept, misconception, lesson_id, sort_order, is_published, source_references)
select z.id, 'core', null, 'q07-compounding', 'Compounding', 'Two students each save ₹1,000. Student A leaves positive investment earnings invested. Student B withdraws the earnings each year. Assume the investments generate positive returns and otherwise comparable conditions. Which statement is generally correct?', 'Compounding', 'intermediate', 'Understanding compound growth', 'Thinking withdrawing earnings makes no difference, or that compounding guarantees the investment cannot lose money.', (select id from public.lessons where slug = 'interest-and-compound-growth'), 2, true, '[{"title":"SEBI Investor education portal","publisher":"Securities and Exchange Board of India","url":"https://investor.sebi.gov.in/","note":"Investor education on money matters, investment avenues and risk."},{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."}]'::jsonb
