on conflict (slug) do nothing;
insert into public.quiz_options (question_id, option_key, option_text, sort_order)
select q.id, v.option_key, v.option_text, v.sort_order
from public.quiz_questions q
cross join (values
  ('A', 'Student B must always end with more money.', 1),
  ('B', 'Student A can benefit from earnings generating further earnings.', 2),
  ('C', 'Both students must have exactly the same final balance.', 3),
  ('D', 'Compounding means the investment cannot lose money.', 4)
) as v(option_key, option_text, sort_order)
where q.slug = 'q07-compounding'
on conflict (question_id, option_key) do nothing;
insert into public.quiz_answer_keys (question_id, correct_option_id, explanation, teaching_point)
select q.id, o.id, 'When earnings remain invested, future growth can occur on both the original amount and previous earnings. Actual investment returns can vary, and compounding does not eliminate risk.', 'Understand compounding without assuming guaranteed returns.'
from public.quiz_questions q join public.quiz_options o on o.question_id = q.id and o.option_key = 'B'
where q.slug = 'q07-compounding'
on conflict (question_id) do nothing;
