  ('B', 'Post the statement on social media to ask for advice.', 2),
  ('C', 'Report it to your bank right away through its official app or the number on your card, and ask to block the card.', 3),
  ('D', 'Call the number in an SMS that offers to help recover the money.', 4)
) as v(option_key, option_text, sort_order)
where q.slug = 'p15-unrecognized-withdrawal'
on conflict (question_id, option_key) do nothing;
insert into public.quiz_answer_keys (question_id, correct_option_id, explanation, teaching_point)
select q.id, o.id, 'POS means a card payment at a shop. Report unrecognised payments promptly through official channels.', 'Report quickly, only through verified channels.'
from public.quiz_questions q join public.quiz_options o on o.question_id = q.id and o.option_key = 'C'
where q.slug = 'p15-unrecognized-withdrawal'
on conflict (question_id) do nothing;

-- Remediation comic scripts (drafts awaiting admin review; not published)
insert into public.remediation_comics (question_id, lesson_id, slug, title, description, topic, concept, misconception, script, takeaway, alt_text, source_references, provider, generation_status, review_status)
select q.id, q.lesson_id, 'comic-q01-budget-puzzle', 'Aarav and the Missing ₹400', 'Remediation for question 1: The Budget Puzzle', 'Budgeting', 'Adding up spending and planned savings', 'Forgetting to subtract planned savings (or one of the expenses) when working out what is left.', '{"characters":["Aarav (Class 11, neat, carries a small notebook)","Asha Didi"],"panels":[{"stage":"situation","setting":"Aarav''s study desk, evening","visual":"Aarav holds ₹2,000 in notes and a notebook listing travel, food and study costs.","dialogue":[{"speaker":"Aarav","line":"Travel ₹650, food ₹450, books ₹300. Easy!"}],"caption":""},{"stage":"misconception","setting":"Same desk","visual":"Aarav grins, writes \"₹600 left for fun!\" in big letters.","dialogue":[{"speaker":"Aarav","line":"₹600 left for a new game!"}],"caption":""},{"stage":"discovery","setting":"Asha Didi leans over his shoulder","visual":"Asha points at a sticky note on his piggy bank that says \"Save ₹400\".","dialogue":[{"speaker":"Asha Didi","line":"Did you forget your savings plan?"}],"caption":""},{"stage":"explanation","setting":"Close-up of the notebook","visual":"A neat subtraction: 2,000 − 650 − 450 − 300 − 400 = 200.","dialogue":[{"speaker":"Asha Didi","line":"Savings is part of the plan too. That leaves ₹200."}],"caption":""},{"stage":"takeaway","setting":"Aarav smiling, ticking the list","visual":"Aarav circles ₹200 and puts ₹400 in the piggy bank.","dialogue":[{"speaker":"Aarav","line":"Count everything first, then spend what''s left."}],"caption":"Include every expense and your savings before you spend."}]}'::jsonb, 'Subtract all planned spending and savings before deciding what is left.', 'Five-panel comic: Aarav forgets to include ₹400 savings in his budget; his cousin helps him recalculate and he finds only ₹200 is left.', '[{"title":"National Centre for Financial Education","publisher":"NCFE (promoted by RBI, SEBI, IRDAI and PFRDA)","url":"https://ncfe.org.in/","note":"Financial education material for students and the public."}]'::jsonb, 'comicsmaker_manual', 'script_ready', 'in_review'
from public.quiz_questions q where q.slug = 'q01-budget-puzzle'
on conflict (slug) do nothing;
insert into public.remediation_comics (question_id, lesson_id, slug, title, description, topic, concept, misconception, script, takeaway, alt_text, source_references, provider, generation_status, review_status)
select q.id, q.lesson_id, 'comic-q02-emergency-or-temptation', 'Nisha''s Calculator Crisis', 'Remediation for question 2: Emergency or Temptation?', 'Emergency savings', 'Using and rebuilding emergency savings', 'Believing savings should never be touched, or reaching for a loan before using money set aside for emergencies.', '{"characters":["Nisha (Class 12, ponytail, exam notes everywhere)","Asha Didi"],"panels":[{"stage":"situation","setting":"Nisha''s room, night before an exam","visual":"Nisha presses buttons on a blank calculator screen, worried.","dialogue":[{"speaker":"Nisha","line":"My calculator died! The exam is tomorrow!"}],"caption":""},{"stage":"misconception","setting":"Nisha on her phone","visual":"Phone screen shows an ad: \"Instant loan in 5 minutes!\"","dialogue":[{"speaker":"Nisha","line":"I can''t touch my savings. Maybe I should borrow?"}],"caption":""},{"stage":"discovery","setting":"Asha Didi at the door","visual":"Asha holds up a jar labelled \"Emergency ₹1,200\".","dialogue":[{"speaker":"Asha Didi","line":"Isn''t this exactly what that jar is for?"}],"caption":""},{"stage":"explanation","setting":"Both at the desk","visual":"Split image: ₹700 for calculator; jar shows ₹500 and a plan \"+₹150/month\".","dialogue":[{"speaker":"Asha Didi","line":"Use ₹700 for a necessary, unexpected cost. Then rebuild it."}],"caption":""},{"stage":"takeaway","setting":"Nisha with a new calculator, writing a savings plan","visual":"Nisha smiles and adds a coin to the jar.","dialogue":[{"speaker":"Nisha","line":"Savings give me choices. Now I refill them!"}],"caption":"Emergency savings are for necessary surprises. Rebuild them after."}]}'::jsonb, 'Emergency savings exist for necessary, unexpected costs. Use them wisely and rebuild them.', 'Five-panel comic: Nisha''s calculator breaks before an exam; instead of borrowing, she uses ₹700 of her emergency savings and plans to rebuild them.', '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."},{"title":"National Centre for Financial Education","publisher":"NCFE (promoted by RBI, SEBI, IRDAI and PFRDA)","url":"https://ncfe.org.in/","note":"Financial education material for students and the public."}]'::jsonb, 'comicsmaker_manual', 'script_ready', 'in_review'
from public.quiz_questions q where q.slug = 'q02-emergency-or-temptation'
on conflict (slug) do nothing;
insert into public.remediation_comics (question_id, lesson_id, slug, title, description, topic, concept, misconception, script, takeaway, alt_text, source_references, provider, generation_status, review_status)
select q.id, q.lesson_id, 'comic-q03-bank-nominee', 'Kabir Explains the Nominee', 'Remediation for question 3: Understanding a Bank Nominee', 'Banking basics', 'Understanding a bank nominee', 'Thinking a nominee can use the account or receives its earnings while the account holder is alive.', '{"characters":["Kabir (Class 12, tall, helpful)","Kabir''s mother (holding a bank form)","Asha Didi"],"panels":[{"stage":"situation","setting":"Living room, bank passbook and a form on the table","visual":"Kabir''s mother points at the \"Nominee\" box on a form.","dialogue":[{"speaker":"Mother","line":"What does \"nominee\" mean, beta?"}],"caption":""},{"stage":"misconception","setting":"Kabir thinking, thought bubble","visual":"Thought bubble: the nominee withdrawing cash every month.","dialogue":[{"speaker":"Kabir","line":"Maybe they can use the account and get the interest?"}],"caption":""},{"stage":"discovery","setting":"Asha Didi on a video call on the phone","visual":"Asha shakes her head kindly.","dialogue":[{"speaker":"Asha Didi","line":"Not quite! A nominee doesn''t use the account now."}],"caption":""},{"stage":"explanation","setting":"Simple diagram on screen","visual":"Diagram: account holder → (after death, as per rules) → nominee claims the money.","dialogue":[{"speaker":"Asha Didi","line":"It''s the person who can claim the money after the holder''s death, following the bank''s rules."}],"caption":""},{"stage":"takeaway","setting":"Mother filling in the form","visual":"Kabir gives a thumbs up.","dialogue":[{"speaker":"Kabir","line":"It makes things easier for the family later."}],"caption":"A nominee helps the family claim the account later, not use it now."}]}'::jsonb, 'A nominee can claim the account proceeds after the holder''s death under applicable rules. They cannot use the account while the holder is alive.', 'Five-panel comic: Kabir thinks a nominee can use his mother''s account; his cousin explains a nominee only claims the money after the holder''s death under the bank''s rules.', '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."},{"title":"Banking Terminologies (document hosted on Scribd)","publisher":"Scribd user upload","url":"https://www.scribd.com/document/294551371/Banking-Terminologies","note":"Older glossary of general banking terms (cheques, interest, overdraft). Some figures in it are outdated; not used for current rules."}]'::jsonb, 'comicsmaker_manual', 'script_ready', 'in_review'
from public.quiz_questions q where q.slug = 'q03-bank-nominee'
on conflict (slug) do nothing;
insert into public.remediation_comics (question_id, lesson_id, slug, title, description, topic, concept, misconception, script, takeaway, alt_text, source_references, provider, generation_status, review_status)
select q.id, q.lesson_id, 'comic-q04-debit-card-basics', 'Where Did Tara''s ₹180 Go?', 'Remediation for question 4: Debit Card Basics', 'Banking basics', 'How a debit card payment works', 'Confusing a debit card with a credit card (a loan), or thinking a card payment adds money.', '{"characters":["Tara (Class 11, short hair, stationery lover)","Dev","Asha Didi"],"panels":[{"stage":"situation","setting":"Stationery shop counter","visual":"Tara taps her debit card on the card machine; screen shows ₹180.","dialogue":[{"speaker":"Tara","line":"Done! ₹180 for my art supplies."}],"caption":""},{"stage":"misconception","setting":"Outside the shop","visual":"Dev waves his hands excitedly.","dialogue":[{"speaker":"Dev","line":"Cards are like free money, right? Or a loan?"}],"caption":""},{"stage":"discovery","setting":"Tara checks her bank app","visual":"Phone shows balance: ₹1,500 → ₹1,320.","dialogue":[{"speaker":"Tara","line":"Wait, my balance went down by ₹180."}],"caption":""},{"stage":"explanation","setting":"Asha Didi with two cards drawn on a whiteboard","visual":"Left: \"Debit = your money\". Right: \"Credit = borrowed, must repay\".","dialogue":[{"speaker":"Asha Didi","line":"A debit card pays from money already in your account."}],"caption":""},{"stage":"takeaway","setting":"Tara and Dev nodding","visual":"Tara holds up her debit card.","dialogue":[{"speaker":"Tara","line":"Debit uses my money. Credit is a loan."}],"caption":"Debit cards spend your own money; credit cards are borrowing."}]}'::jsonb, 'A debit card payment is deducted from your linked account. A credit card is a loan you repay.', 'Five-panel comic: Tara pays ₹180 by debit card, sees her balance drop by ₹180, and learns the difference between debit and credit cards.', '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."}]'::jsonb, 'comicsmaker_manual', 'script_ready', 'in_review'
from public.quiz_questions q where q.slug = 'q04-debit-card-basics'
on conflict (slug) do nothing;
insert into public.remediation_comics (question_id, lesson_id, slug, title, description, topic, concept, misconception, script, takeaway, alt_text, source_references, provider, generation_status, review_status)
select q.id, q.lesson_id, 'comic-q05-spending-trade-off', 'Rohan''s ₹1,150 Wishlist', 'Remediation for question 5: The Spending Trade-Off', 'Budgeting', 'Balancing spending and savings goals', 'Assuming that because each item is affordable on its own, all of them together are affordable.', '{"characters":["Rohan (Class 11, gamer t-shirt)","Asha Didi"],"panels":[{"stage":"situation","setting":"Rohan''s room","visual":"Rohan holds three cards: Game ₹650, Outing ₹300, Save ₹200. A wallet shows ₹900.","dialogue":[{"speaker":"Rohan","line":"I have ₹900. Each one is less than that!"}],"caption":""},{"stage":"misconception","setting":"Rohan celebrating","visual":"Rohan imagines doing all three at once.","dialogue":[{"speaker":"Rohan","line":"So I can do all of them!"}],"caption":""},{"stage":"discovery","setting":"Asha Didi stacks the cards","visual":"A tall stack labelled ₹1,150 next to a shorter stack ₹900.","dialogue":[{"speaker":"Asha Didi","line":"Add them up together first."}],"caption":""},{"stage":"explanation","setting":"Whiteboard","visual":"650 + 300 + 200 = 1,150. 1,150 − 900 = 250 short.","dialogue":[{"speaker":"Asha Didi","line":"You''re ₹250 short. Something has to change."}],"caption":""},{"stage":"takeaway","setting":"Rohan choosing","visual":"Rohan moves \"Game\" to \"Next month\" and keeps savings.","dialogue":[{"speaker":"Rohan","line":"Rank priorities, then adjust."}],"caption":"Check the combined cost of all your plans."}]}'::jsonb, 'Add up all your plans together. If they exceed what you have, adjust; do not automatically drop savings.', 'Five-panel comic: Rohan thinks he can afford a game, an outing and savings because each costs less than ₹900, but together they total ₹1,150.', '[{"title":"National Centre for Financial Education","publisher":"NCFE (promoted by RBI, SEBI, IRDAI and PFRDA)","url":"https://ncfe.org.in/","note":"Financial education material for students and the public."}]'::jsonb, 'comicsmaker_manual', 'script_ready', 'in_review'
from public.quiz_questions q where q.slug = 'q05-spending-trade-off'
on conflict (slug) do nothing;
insert into public.remediation_comics (question_id, lesson_id, slug, title, description, topic, concept, misconception, script, takeaway, alt_text, source_references, provider, generation_status, review_status)
select q.id, q.lesson_id, 'comic-q06-three-month-goal', 'Meera''s Trip Plan', 'Remediation for question 6: A Three-Month Goal', 'Goal planning', 'Saving toward a near-term goal', 'Trying to reach a short-term goal faster by taking investment risk with money needed soon.', '{"characters":["Meera (Class 12, braids, travel poster on wall)","Dev","Asha Didi"],"panels":[{"stage":"situation","setting":"School corridor, trip poster: \"Hampi trip ₹3,000 — in 3 months\"","visual":"Meera checks her savings app: ₹2,400.","dialogue":[{"speaker":"Meera","line":"I need ₹600 more in three months."}],"caption":""},{"stage":"misconception","setting":"Dev showing his phone","visual":"Phone shows an ad: \"Double your money fast!\"","dialogue":[{"speaker":"Dev","line":"Put it all in this! You''ll have ₹4,800!"}],"caption":""},{"stage":"discovery","setting":"Asha Didi with a calendar","visual":"Calendar shows 3 months with ₹200 marked on each.","dialogue":[{"speaker":"Asha Didi","line":"What if it falls right before the trip?"}],"caption":""},{"stage":"explanation","setting":"Simple chart","visual":"₹2,400 + ₹200 + ₹200 + ₹200 = ₹3,000 in a safe, accessible account.","dialogue":[{"speaker":"Asha Didi","line":"Short goals need safe, steady saving."}],"caption":""},{"stage":"takeaway","setting":"Meera at the trip, smiling","visual":"Meera holds a ticket.","dialogue":[{"speaker":"Meera","line":"Match the plan to the deadline!"}],"caption":"Money needed soon belongs somewhere safe and accessible."}]}'::jsonb, 'For a short-term goal, save steadily in a safe, accessible place instead of taking investment risk.', 'Five-panel comic: Meera needs ₹600 more for a trip in three months; instead of a risky scheme, she saves ₹200 a month safely.', '[{"title":"SEBI Investor education portal","publisher":"Securities and Exchange Board of India","url":"https://investor.sebi.gov.in/","note":"Investor education on money matters, investment avenues and risk."},{"title":"National Centre for Financial Education","publisher":"NCFE (promoted by RBI, SEBI, IRDAI and PFRDA)","url":"https://ncfe.org.in/","note":"Financial education material for students and the public."}]'::jsonb, 'comicsmaker_manual', 'script_ready', 'in_review'
from public.quiz_questions q where q.slug = 'q06-three-month-goal'
on conflict (slug) do nothing;
insert into public.remediation_comics (question_id, lesson_id, slug, title, description, topic, concept, misconception, script, takeaway, alt_text, source_references, provider, generation_status, review_status)
select q.id, q.lesson_id, 'comic-q07-compounding', 'The Snowball Savers', 'Remediation for question 7: Compounding', 'Compounding', 'Understanding compound growth', 'Thinking withdrawing earnings makes no difference, or that compounding guarantees the investment cannot lose money.', '{"characters":["Student A: Ira (calm, patient)","Student B: Sameer (spends earnings each year)","Asha Didi"],"panels":[{"stage":"situation","setting":"Two students with matching ₹1,000 jars","visual":"Ira and Sameer each hold a jar labelled ₹1,000.","dialogue":[{"speaker":"Sameer","line":"Same start, same result, right?"}],"caption":""},{"stage":"misconception","setting":"One year later","visual":"Sameer takes out his earnings to buy snacks; Ira leaves hers in.","dialogue":[{"speaker":"Sameer","line":"Taking out the extra makes no difference."}],"caption":""},{"stage":"discovery","setting":"A few years later","visual":"Ira''s jar has visibly more coins than Sameer''s.","dialogue":[{"speaker":"Ira","line":"My earnings started earning too!"}],"caption":""},{"stage":"explanation","setting":"Asha Didi with a snowball rolling downhill, getting bigger","visual":"Labels on snowball layers: start, year-1 earnings, earnings on earnings.","dialogue":[{"speaker":"Asha Didi","line":"That''s compounding. But returns can also go down; it''s not a guarantee."}],"caption":""},{"stage":"takeaway","setting":"Both students planning together","visual":"Sameer writes \"leave earnings in\" on his jar.","dialogue":[{"speaker":"Sameer","line":"Time + patience can help growth, with risk in mind."}],"caption":"Compounding = earning on earnings. It does not remove risk."}]}'::jsonb, 'Leaving positive earnings invested lets future growth build on past growth. Compounding does not guarantee returns or remove risk.', 'Five-panel comic: two students start with ₹1,000; the one who leaves earnings invested ends up with more, illustrating compounding and its risks.', '[{"title":"SEBI Investor education portal","publisher":"Securities and Exchange Board of India","url":"https://investor.sebi.gov.in/","note":"Investor education on money matters, investment avenues and risk."},{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."}]'::jsonb, 'comicsmaker_manual', 'script_ready', 'in_review'
from public.quiz_questions q where q.slug = 'q07-compounding'
on conflict (slug) do nothing;
insert into public.remediation_comics (question_id, lesson_id, slug, title, description, topic, concept, misconception, script, takeaway, alt_text, source_references, provider, generation_status, review_status)
select q.id, q.lesson_id, 'comic-q08-diversification-detective', 'Ishaan''s Basket of Eggs', 'Remediation for question 8: Diversification Detective', 'Diversification', 'Diversification and concentration risk', 'Believing diversification guarantees no losses or higher returns.', '{"characters":["Ishaan (Class 12, detective cap for fun)","Asha Didi"],"panels":[{"stage":"situation","setting":"Ishaan at a laptop with ₹5,000 for long-term investing","visual":"Screen shows one company''s logo.","dialogue":[{"speaker":"Ishaan","line":"I''ll put everything into this one company!"}],"caption":""},{"stage":"misconception","setting":"Ishaan daydreaming","visual":"Thought bubble: \"Spread it out = never lose money.\"","dialogue":[{"speaker":"Ishaan","line":"Or spread it, then I can never lose. Right?"}],"caption":""},{"stage":"discovery","setting":"Asha Didi holding one basket with all eggs, one egg cracked","visual":"A second picture: eggs spread across many baskets.","dialogue":[{"speaker":"Asha Didi","line":"If one basket drops, you lose fewer eggs when they''re spread out."}],"caption":""},{"stage":"explanation","setting":"Whiteboard","visual":"Arrow: diversification → reduces concentration risk. Crossed out: \"no risk\", \"guaranteed profit\".","dialogue":[{"speaker":"Asha Didi","line":"It reduces risk from one company. It can''t remove all risk."}],"caption":""},{"stage":"takeaway","setting":"Ishaan nodding","visual":"Ishaan writes \"Spread ≠ Safe from all risk\".","dialogue":[{"speaker":"Ishaan","line":"Case closed: spreading helps, but no guarantees."}],"caption":"Diversification reduces concentration risk, not all risk."}]}'::jsonb, 'Diversification can soften the impact of a problem at one company. It does not guarantee profit or eliminate risk.', 'Five-panel comic using eggs in baskets to show that spreading investments reduces the damage from one company''s problem but does not remove all risk.', '[{"title":"SEBI Investor education portal","publisher":"Securities and Exchange Board of India","url":"https://investor.sebi.gov.in/","note":"Investor education on money matters, investment avenues and risk."}]'::jsonb, 'comicsmaker_manual', 'script_ready', 'in_review'
from public.quiz_questions q where q.slug = 'q08-diversification-detective'
on conflict (slug) do nothing;
insert into public.remediation_comics (question_id, lesson_id, slug, title, description, topic, concept, misconception, script, takeaway, alt_text, source_references, provider, generation_status, review_status)
select q.id, q.lesson_id, 'comic-q09-hidden-fee', 'The Fee That Nibbles', 'Remediation for question 9: The Hidden Fee', 'Investment fees', 'How fees affect money invested', 'Assuming a higher fee means better performance, or that fees do not matter.', '{"characters":["Dev","Asha Didi"],"panels":[{"stage":"situation","setting":"Two similar fund brochures on a table: Fund A fee ₹20/year, Fund B fee ₹100/year","visual":"Dev compares them.","dialogue":[{"speaker":"Dev","line":"Fund B costs more. It must be better!"}],"caption":""},{"stage":"misconception","setting":"Dev pointing at B","visual":"Dev imagines B wearing a crown.","dialogue":[{"speaker":"Dev","line":"Expensive means premium, right?"}],"caption":""},{"stage":"discovery","setting":"Asha Didi draws two piggy banks","visual":"A small mouse labelled \"fee\" nibbles ₹20 from A and ₹100 from B.","dialogue":[{"speaker":"Asha Didi","line":"Same returns before fees. Which keeps more?"}],"caption":""},{"stage":"explanation","setting":"Calculation bubble","visual":"₹100 − ₹20 = ₹80 more stays invested with Fund A each year.","dialogue":[{"speaker":"Asha Didi","line":"All else equal, lower fees leave more money working for you."}],"caption":""},{"stage":"takeaway","setting":"Dev checking a fee label","visual":"Dev holds a magnifying glass over \"expense ratio\".","dialogue":[{"speaker":"Dev","line":"Always check the fees. Higher fees don''t guarantee better results."}],"caption":"Fees reduce what you keep."}]}'::jsonb, 'With similar funds and returns, lower fees leave more money invested. A higher fee is not proof of better performance.', 'Five-panel comic: a fee mouse nibbles ₹20 from one fund and ₹100 from another, showing that lower fees leave more money invested.', '[{"title":"SEBI Investor education portal","publisher":"Securities and Exchange Board of India","url":"https://investor.sebi.gov.in/","note":"Investor education on money matters, investment avenues and risk."}]'::jsonb, 'comicsmaker_manual', 'script_ready', 'in_review'
from public.quiz_questions q where q.slug = 'q09-hidden-fee'
on conflict (slug) do nothing;
insert into public.remediation_comics (question_id, lesson_id, slug, title, description, topic, concept, misconception, script, takeaway, alt_text, source_references, provider, generation_status, review_status)
select q.id, q.lesson_id, 'comic-q10-inflation-purchasing-power', 'The Notebook That Got Pricier', 'Remediation for question 10: Inflation and Purchasing Power', 'Inflation', 'Inflation and purchasing power', 'Thinking that any growth in savings means you can buy more, regardless of price rises.', '{"characters":["Pooja (Class 11, loves notebooks)","Asha Didi"],"panels":[{"stage":"situation","setting":"Stationery shop, this year","visual":"Notebook price tag ₹100. Pooja has ₹100.","dialogue":[{"speaker":"Pooja","line":"I''ll buy it next year. My savings will grow!"}],"caption":""},{"stage":"misconception","setting":"Pooja proudly showing savings app","visual":"App shows ₹100 → ₹103.","dialogue":[{"speaker":"Pooja","line":"More money = I can buy more!"}],"caption":""},{"stage":"discovery","setting":"Same shop, next year","visual":"Price tag now ₹105. Pooja has ₹103.","dialogue":[{"speaker":"Pooja","line":"Wait, I''m ₹2 short?"}],"caption":""},{"stage":"explanation","setting":"Asha Didi with two arrows","visual":"Price arrow +₹5 taller than savings arrow +₹3.","dialogue":[{"speaker":"Asha Didi","line":"Prices rose faster than your savings. That''s lower purchasing power."}],"caption":""},{"stage":"takeaway","setting":"Pooja comparing both arrows","visual":"Pooja writes \"Compare growth vs prices\".","dialogue":[{"speaker":"Pooja","line":"Having more rupees isn''t the same as buying more."}],"caption":"Compare how fast money grows with how fast prices rise."}]}'::jsonb, 'If prices rise faster than your savings, your purchasing power falls even though you have more rupees.', 'Five-panel comic: a ₹100 notebook rises to ₹105 while Pooja''s savings grow to ₹103, showing reduced purchasing power.', '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."}]'::jsonb, 'comicsmaker_manual', 'script_ready', 'in_review'
from public.quiz_questions q where q.slug = 'q10-inflation-purchasing-power'
on conflict (slug) do nothing;
insert into public.remediation_comics (question_id, lesson_id, slug, title, description, topic, concept, misconception, script, takeaway, alt_text, source_references, provider, generation_status, review_status)
select q.id, q.lesson_id, 'comic-q11-fake-refund', 'The Refund That Wasn''t', 'Remediation for question 11: The Fake Refund', 'UPI safety', 'Fake UPI refund requests', 'Believing a UPI PIN or QR scan is needed to receive money.', '{"characters":["Neha (Class 12, sells handmade bookmarks online)","Asha Didi"],"panels":[{"stage":"situation","setting":"Neha on her phone","visual":"Chat from \"Seller Support\": \"Scan this QR and enter UPI PIN to get ₹750 refund.\"","dialogue":[{"speaker":"Neha","line":"Oh nice, a refund!"}],"caption":""},{"stage":"misconception","setting":"Neha about to type her PIN","visual":"Thumb hovering over the PIN pad.","dialogue":[{"speaker":"Neha","line":"I just need my PIN to receive it, right?"}],"caption":""},{"stage":"discovery","setting":"Asha Didi gently stops her","visual":"Big warning sign icon above the screen: \"PIN = money OUT\".","dialogue":[{"speaker":"Asha Didi","line":"Stop! You never need a PIN to receive money."}],"caption":""},{"stage":"explanation","setting":"Split panel","visual":"Left: entering PIN sends money. Right: Neha opens the official app to check the refund status.","dialogue":[{"speaker":"Asha Didi","line":"Check refunds in the official app or seller channel. Never share PIN or OTP."}],"caption":""},{"stage":"takeaway","setting":"Neha blocking the contact","visual":"Neha taps \"Block & Report\".","dialogue":[{"speaker":"Neha","line":"PIN is for paying, never for receiving!"}],"caption":"Never enter your UPI PIN to receive money."}]}'::jsonb, 'A UPI PIN authorises money leaving your account. You never need it to receive money. Verify refunds through official channels.', 'Five-panel comic: Neha is asked to scan a QR code and enter her UPI PIN for a refund; her cousin explains a PIN is only for sending money.', '[{"title":"UPI product information and safety guidance","publisher":"National Payments Corporation of India","url":"https://www.npci.org.in/","note":"Operator of UPI. Refer to the official site for current safety advice."},{"title":"National Cyber Crime Reporting Portal (helpline 1930)","publisher":"Ministry of Home Affairs, Government of India","url":"https://cybercrime.gov.in/","note":"Official channel to report cyber financial fraud."}]'::jsonb, 'comicsmaker_manual', 'script_ready', 'in_review'
from public.quiz_questions q where q.slug = 'q11-fake-refund'
on conflict (slug) do nothing;
insert into public.remediation_comics (question_id, lesson_id, slug, title, description, topic, concept, misconception, script, takeaway, alt_text, source_references, provider, generation_status, review_status)
select q.id, q.lesson_id, 'comic-q12-urgent-bank-message', 'Ten Minutes to Panic', 'Remediation for question 12: The Urgent Bank Message', 'Phishing', 'Phishing and urgent bank messages', 'Trusting a message because it shows a bank logo or uses your name.', '{"characters":["Dev","Asha Didi"],"panels":[{"stage":"situation","setting":"Dev''s phone buzzes","visual":"SMS with a bank logo: \"Account blocked in 10 minutes! Click link and log in.\"","dialogue":[{"speaker":"Dev","line":"It has the bank''s logo! I''d better hurry!"}],"caption":""},{"stage":"misconception","setting":"Dev about to tap the link","visual":"A countdown clock in the background.","dialogue":[{"speaker":"Dev","line":"It even knows my name. It must be real!"}],"caption":""},{"stage":"discovery","setting":"Asha Didi points at the message","visual":"Red circles around \"10 minutes\" and the link.","dialogue":[{"speaker":"Asha Didi","line":"Urgency plus a login link? Classic phishing."}],"caption":""},{"stage":"explanation","setting":"Asha Didi shows how to verify","visual":"Dev opens the official bank app himself; no alert there.","dialogue":[{"speaker":"Asha Didi","line":"Logos can be copied. Go to the bank directly, never through the link."}],"caption":""},{"stage":"takeaway","setting":"Dev reporting the SMS","visual":"Dev deletes and reports the message.","dialogue":[{"speaker":"Dev","line":"Pause, don''t click, verify officially."}],"caption":"Urgency + request for details = warning sign."}]}'::jsonb, 'Urgent threats asking for login details through a link are a phishing sign. Verify by opening the official app or website yourself.', 'Five-panel comic: Dev receives an urgent SMS with a bank logo and a login link; his cousin shows him how to verify through the official app instead.', '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."},{"title":"National Cyber Crime Reporting Portal (helpline 1930)","publisher":"Ministry of Home Affairs, Government of India","url":"https://cybercrime.gov.in/","note":"Official channel to report cyber financial fraud."}]'::jsonb, 'comicsmaker_manual', 'script_ready', 'in_review'
from public.quiz_questions q where q.slug = 'q12-urgent-bank-message'
on conflict (slug) do nothing;
insert into public.remediation_comics (question_id, lesson_id, slug, title, description, topic, concept, misconception, script, takeaway, alt_text, source_references, provider, generation_status, review_status)
select q.id, q.lesson_id, 'comic-q13-guaranteed-return-influencer', 'Too Good to Be True', 'Remediation for question 13: The Guaranteed-Return Influencer', 'Investment fraud', 'Unrealistic investment promises', 'Believing specific numbers, positive comments or a small successful test prove an offer is legitimate.', '{"characters":["Aditi (Class 12, follows lots of influencers)","Asha Didi"],"panels":[{"stage":"situation","setting":"Aditi scrolling reels","visual":"Influencer video: \"₹2,000 → ₹10,000 in 30 days! Zero risk!\"","dialogue":[{"speaker":"Aditi","line":"Look at all these happy comments!"}],"caption":""},{"stage":"misconception","setting":"Aditi opening her UPI app","visual":"Aditi types ₹500.","dialogue":[{"speaker":"Aditi","line":"I''ll just test with ₹500 first."}],"caption":""},{"stage":"discovery","setting":"Asha Didi with a \"red flags\" checklist","visual":"Checklist: Guaranteed? Zero risk? Super fast? Pressure? All ticked.","dialogue":[{"speaker":"Asha Didi","line":"Every red flag is ticked."}],"caption":""},{"stage":"explanation","setting":"Asha Didi explaining","visual":"Illustration: small payout first, then a big loss.","dialogue":[{"speaker":"Asha Didi","line":"Scams can pay a small amount first to win trust. Check SEBI registration."}],"caption":""},{"stage":"takeaway","setting":"Aditi closing the app","visual":"Aditi reports the video.","dialogue":[{"speaker":"Aditi","line":"No real investment is risk-free and guaranteed."}],"caption":"Big, fast, guaranteed returns are a major warning sign."}]}'::jsonb, 'Extraordinary returns with "zero risk" are serious warning signs. A small successful test does not prove an offer is legitimate.', 'Five-panel comic: Aditi sees an influencer promising 5× returns with zero risk; her cousin points out the red flags and the small-test trap.', '[{"title":"SEBI Investor education portal","publisher":"Securities and Exchange Board of India","url":"https://investor.sebi.gov.in/","note":"Investor education on money matters, investment avenues and risk."},{"title":"Sachet portal for reporting illegal deposit schemes","publisher":"Reserve Bank of India","url":"https://sachet.rbi.org.in/","note":"Check and report unauthorised entities collecting deposits."}]'::jsonb, 'comicsmaker_manual', 'script_ready', 'in_review'
from public.quiz_questions q where q.slug = 'q13-guaranteed-return-influencer'
on conflict (slug) do nothing;
insert into public.remediation_comics (question_id, lesson_id, slug, title, description, topic, concept, misconception, script, takeaway, alt_text, source_references, provider, generation_status, review_status)
select q.id, q.lesson_id, 'comic-q14-money-needed-soon', 'Ananya''s Exam Fee', 'Remediation for question 14: Money Needed Soon', 'Time horizon', 'Protecting money needed soon', 'Assuming a recent price rise will continue, and ignoring when the money is needed.', '{"characters":["Ananya (Class 12, focused, exam timetable on wall)","Dev","Asha Didi"],"panels":[{"stage":"situation","setting":"Ananya''s room, calendar marked \"Exam fee ₹4,000 due in 2 months\"","visual":"Ananya has exactly ₹4,000 saved.","dialogue":[{"speaker":"Ananya","line":"Fee money: sorted."}],"caption":""},{"stage":"misconception","setting":"Dev shows a chart rising sharply this week","visual":"Chart going up.","dialogue":[{"speaker":"Dev","line":"This went up all week! Invest and earn extra!"}],"caption":""},{"stage":"discovery","setting":"Asha Didi extends the chart","visual":"The chart continues and dips right on the fee date.","dialogue":[{"speaker":"Asha Didi","line":"What if it dips the week your fee is due?"}],"caption":""},{"stage":"explanation","setting":"Two boxes","visual":"Left: \"Needed soon → safe & accessible\". Right: \"Long-term → can consider risk\".","dialogue":[{"speaker":"Asha Didi","line":"Money for a fixed, near-term need shouldn''t ride price swings."}],"caption":""},{"stage":"takeaway","setting":"Ananya paying the fee on time","visual":"Ananya smiles at the receipt.","dialogue":[{"speaker":"Ananya","line":"Match the money to its purpose and timing."}],"caption":"Keep near-term essential money safe."}]}'::jsonb, 'Money required soon for an essential expense should stay safe and accessible, not exposed to volatility.', 'Five-panel comic: Ananya is tempted to invest her ₹4,000 exam fee in an asset that rose this week; her cousin shows how a dip could leave her short.', '[{"title":"SEBI Investor education portal","publisher":"Securities and Exchange Board of India","url":"https://investor.sebi.gov.in/","note":"Investor education on money matters, investment avenues and risk."}]'::jsonb, 'comicsmaker_manual', 'script_ready', 'in_review'
from public.quiz_questions q where q.slug = 'q14-money-needed-soon'
on conflict (slug) do nothing;
insert into public.remediation_comics (question_id, lesson_id, slug, title, description, topic, concept, misconception, script, takeaway, alt_text, source_references, provider, generation_status, review_status)
select q.id, q.lesson_id, 'comic-q15-unrecognized-withdrawal', 'The Mystery ATM Withdrawal', 'Remediation for question 15: The Unrecognized Withdrawal', 'Reporting fraud', 'Reporting an unfamiliar bank transaction', 'Ignoring an unfamiliar transaction, or trusting someone who contacts you offering to recover money.', '{"characters":["Farhan (Class 11, checks statements carefully)","Asha Didi"],"panels":[{"stage":"situation","setting":"Farhan reading his bank statement on the app","visual":"Entry highlighted: \"ATM WDL ₹1,000\".","dialogue":[{"speaker":"Farhan","line":"I didn''t withdraw ₹1,000!"}],"caption":""},{"stage":"misconception","setting":"Farhan''s phone pings","visual":"Message: \"We can recover your money. Share OTP.\" Farhan also thinks about ignoring it.","dialogue":[{"speaker":"Farhan","line":"Maybe I''ll ignore it... or let this person help?"}],"caption":""},{"stage":"discovery","setting":"Asha Didi points at the message","visual":"Red X over the unsolicited message.","dialogue":[{"speaker":"Asha Didi","line":"Never share an OTP with someone who contacts you first."}],"caption":""},{"stage":"explanation","setting":"Farhan calling the number printed on his debit card","visual":"Checklist: report to bank, block card, note reference number, cybercrime.gov.in / 1930 for cyber fraud.","dialogue":[{"speaker":"Asha Didi","line":"Report it quickly through official channels."}],"caption":""},{"stage":"takeaway","setting":"Farhan with a complaint reference number","visual":"Farhan relieved.","dialogue":[{"speaker":"Farhan","line":"Spot it, report it, the safe way."}],"caption":"Report unfamiliar transactions promptly through verified channels."}]}'::jsonb, 'If a transaction looks unfamiliar, contact your bank promptly through its official app, website or verified number. Never share credentials with unsolicited "recovery" contacts.', 'Five-panel comic: Farhan finds an ATM withdrawal he did not make, ignores a fake recovery message, and reports it to his bank through the number on his card.', '[{"title":"Financial Education resources (FAME messages, Financial Literacy Week)","publisher":"Reserve Bank of India","url":"https://www.rbi.org.in/FinancialEducation/","note":"Official awareness material on banking basics, KYC and safe digital banking."},{"title":"National Cyber Crime Reporting Portal (helpline 1930)","publisher":"Ministry of Home Affairs, Government of India","url":"https://cybercrime.gov.in/","note":"Official channel to report cyber financial fraud."},{"title":"RBI Complaint Management System (Integrated Ombudsman Scheme)","publisher":"Reserve Bank of India","url":"https://cms.rbi.org.in/","note":"Escalation route if a bank does not resolve a complaint."}]'::jsonb, 'comicsmaker_manual', 'script_ready', 'in_review'
from public.quiz_questions q where q.slug = 'q15-unrecognized-withdrawal'
on conflict (slug) do nothing;
